/**
 * @distilled.cloud/mailchimp — Mailchimp Marketing and Transactional API SDK
 * for Effect.
 *
 * `./services` is generated by `scripts/generate.ts`; everything else in this
 * folder is hand-written. Marketing operations are exported flat; the
 * Transactional API (formerly Mandrill) is under `Transactional`, with its
 * own key.
 *
 * @example
 * ```ts
 * import * as Effect from "effect/Effect";
 * import * as FetchHttpClient from "effect/unstable/http/FetchHttpClient";
 * import * as Mailchimp from "@distilled.cloud/mailchimp";
 *
 * const program = Mailchimp.setListMember({
 *   list_id: "a1b2c3d4e5",
 *   subscriber_hash: Mailchimp.subscriberHash("ada@example.com"),
 *   email_address: "ada@example.com",
 *   status_if_new: "subscribed",
 * }).pipe(
 *   Effect.provide(Mailchimp.fromApiKey({ apiKey: "…-us21" })),
 *   Effect.provide(FetchHttpClient.layer),
 * );
 *
 * const send = Mailchimp.Transactional.sendMessage({
 *   message: { to: [{ email: "ada@example.com" }], subject: "Hi", text: "…" },
 * }).pipe(
 *   Effect.provide(Mailchimp.fromTransactionalApiKey({ apiKey: "md-…" })),
 *   Effect.provide(FetchHttpClient.layer),
 * );
 * ```
 */
export * from "./credentials.ts";
export * as T from "./traits.ts";
export * as Retry from "./retry.ts";
export {
  MailchimpProtocol,
  MailchimpTransactionalProtocol,
  type MailchimpOpError,
  type MailchimpOpContext,
  type MailchimpTransactionalOpError,
  type MailchimpTransactionalOpContext,
} from "./protocol.ts";
export * from "./errors.ts";
export { paginateOffset } from "./pagination.ts";
export { md5, subscriberHash } from "./subscriber-hash.ts";
export * as Services from "./services/index.ts";
export * from "./services/marketing.ts";
export * as Transactional from "./services/transactional.ts";
